"""Generate additive phase-6 schemas and BigQuery DDL independently of contract v1."""

from __future__ import annotations

import argparse
import json
import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
sys.path.insert(0, str(ROOT))

from scripts.export_knowledge_contract import bq_type
from src.models.knowledge_operations import OPERATIONS_MODELS


def artifacts():
    output = {}
    sql = [
        "-- Generated by scripts/export_knowledge_operations.py. Additive phase-6 tables.",
        "-- Apply migrations 001/002 first, with workers stopped. No automatic cloud execution.",
    ]
    for name, model in OPERATIONS_MODELS.items():
        schema = model.model_json_schema()
        output[ROOT / "schemas/knowledge-operations-v1" / f"{name}.schema.json"] = (
            json.dumps(schema, indent=2, ensure_ascii=False) + "\n"
        )
        columns = []
        for field, node in schema["properties"].items():
            kind, nullable = bq_type(node, schema.get("$defs", {}))
            required = "" if nullable or kind.startswith("ARRAY<") else " NOT NULL"
            columns.append(f"  `{field}` {kind}{required}")
        cluster = {
            "finding_dedup_memberships": "dedup_version, group_id, snapshot_id",
            "finding_dedup_state": "dedup_version, snapshot_id",
            "knowledge_processing_attempts": "processing_key",
            "knowledge_batch_checkpoints": "checkpoint_id",
        }[name]
        sql.append(
            f"\nCREATE TABLE IF NOT EXISTS `${{PROJECT_ID}}.${{DATASET}}.{name}` (\n"
            + ",\n".join(columns)
            + f"\n)\nCLUSTER BY {cluster};"
        )
    output[ROOT / "sql/migrations/003_knowledge_operations.sql"] = "\n".join(sql) + "\n"
    return output


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--check", action="store_true")
    args = parser.parse_args()
    for path, content in artifacts().items():
        if args.check:
            if not path.exists() or path.read_text(encoding="utf-8") != content:
                raise SystemExit(f"Outdated artifact: {path}")
        else:
            path.parent.mkdir(parents=True, exist_ok=True)
            path.write_text(content, encoding="utf-8")
    print(
        "Knowledge operations artifacts verified"
        if args.check
        else "Knowledge operations artifacts exported"
    )


if __name__ == "__main__":
    main()
